inductive Nat : Type :=
  | Z : Nat
  | S : Nat -> Nat;

representation Nat := "ouro.nat";

inductive Bool : Type :=
  | True : Bool
  | False : Bool;

intrinsic String : Type := "ouro.string";
intrinsic prim_string_length : String -> Nat := "ouro.string.length";

def add : Nat -> Nat -> Nat :=
  fix add (n : Nat) (m : Nat) : Nat :=
    match n with | Z => m | S k => S (add k m) end;

inductive Unit : Type := | MkUnit : Unit;
def IO (A : Type) : Type := A;
def io_pure (A : Type) (value : A) : IO A := value;
def io_bind (A : Type) (B : Type) (value : IO A) (next : A -> IO B) : IO B := next value;
def choose (flag : Bool) : IO Nat :=
  do let! value := match flag with
       | True => do io_pure Unit MkUnit; io_pure Nat 1
       | False => io_pure Nat 3
       end;
     io_pure Nat value
def result : Nat := add (choose True) (choose False);
